// The Windows app's generated files: one ResourceDictionary with the colour roles and surfaces
// as ThemeDictionaries (Light, Dark and HighContrast, the last mapped to system colours), the
// monospace stack, radii and spacing, and a Style per glyph and icon; and the keys as C#, so
// the app can check at run time that every one of them resolves in every theme.

import { toXamlColor } from './color.mjs';
import { SYSTEM_COLORS, roleTokens, surfaceTokens, monoFamilies, monoFont, radii, spaces, accentShades, hyperlinkTokens, layoutSizes, typeRamp } from './tokens.mjs';
import { MOVING_CLASSES, formatCommands, fmt } from './svg.mjs';

const pascal = (s) => s.split('-').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join('');

export const styleKey = (svg) => (svg.kind === 'glyph' ? `AbGlyph${pascal(svg.name)}` : `AbIcon${pascal(svg.name)}`);

export const xamlHeader = (from) => `Generated by tools/design-gen from ${from}.
     Do not edit: change design/ and run
       node tools/design-gen/generate.mjs
     CI fails when this file is stale against design/.`;

const CAPS = { round: 'Round', square: 'Square', butt: 'Flat' };
const JOINS = { round: 'Round', miter: 'Miter', bevel: 'Bevel' };

// How a part's fill or stroke reaches XAML: currentColor is the control's Foreground, the ink
// is its token, and the knockout is the control's Background (the surface behind the glyph).
function paint(value, part) {
  if (value === undefined || value === 'none') { return null; }
  if (value === 'currentColor') { return '{TemplateBinding Foreground}'; }
  if (part.classes.includes('ink')) { return '{ThemeResource AbNeedsInk}'; }
  if (part.classes.includes('knockout')) { return '{TemplateBinding Background}'; }
  throw new Error(`no XAML paint for ${value}`);
}

function rotate(size) {
  return `<RotateTransform CenterX="${fmt(size / 2)}" CenterY="${fmt(size / 2)}" />`;
}

function partXaml(node, svg, indent, names) {
  const moving = (node.ownClasses ?? node.classes).filter((c) => MOVING_CLASSES.includes(c));
  if (moving.length > 1) { throw new Error(`${svg.file}: a part can move one way only`); }
  const name = moving.length ? pascal(moving[0]) : null;
  if (name) {
    if (names.has(name)) { throw new Error(`${svg.file}: more than one ${moving[0]} part`); }
    names.add(name);
  }
  if (node.tag === 'g') {
    const kids = node.children.map((c) => partXaml(c, svg, `${indent}    `, names)).join('\n');
    if (!name) { return kids.replace(/^ {4}/gm, ''); }
    return `${indent}<Canvas x:Name="${name}">\n${indent}    <Canvas.RenderTransform>${rotate(svg.size)}</Canvas.RenderTransform>\n${kids}\n${indent}</Canvas>`;
  }
  const s = node.style;
  const a = [`Data="F1 ${formatCommands(node.commands)}"`];
  const fill = paint(s.fill, node);
  const stroke = paint(s.stroke, node);
  if (fill) { a.push(`Fill="${fill}"`); }
  if (stroke) {
    const width = Number(s['stroke-width'] ?? 1);
    a.push(`Stroke="${stroke}"`, `StrokeThickness="${fmt(width)}"`);
    const cap = CAPS[s['stroke-linecap'] ?? 'butt'];
    if (cap !== 'Flat') { a.push(`StrokeStartLineCap="${cap}"`, `StrokeEndLineCap="${cap}"`); }
    const join = JOINS[s['stroke-linejoin'] ?? 'miter'];
    // WinUI's miter limit is 10, SVG's 4 (the subset has no stroke-miterlimit). Direct2D measures
    // its miter from the vertex against half the thickness, the same ratio SVG's 4 bounds, so an
    // acute corner bevels in both rather than spiking in XAML.
    if (join !== 'Miter') { a.push(`StrokeLineJoin="${join}"`); } else { a.push('StrokeMiterLimit="4"'); }
    if (s['stroke-dasharray'] && s['stroke-dasharray'] !== 'none') {
      // XAML measures dashes in stroke widths, SVG in user units.
      const dashes = s['stroke-dasharray'].split(/[\s,]+/).filter(Boolean).map((d) => fmt(Number(d) / width));
      a.push(`StrokeDashArray="${dashes.join(' ')}"`);
      if (cap !== 'Flat') { a.push(`StrokeDashCap="${cap}"`); }
    }
  }
  if (node.opacity !== 1) { a.push(`Opacity="${fmt(node.opacity)}"`); }
  if (name) { a.unshift(`x:Name="${name}"`); }
  const open = `${indent}<Path ${a.join(' ')}`;
  return name ? `${open}>\n${indent}    <Path.RenderTransform>${rotate(svg.size)}</Path.RenderTransform>\n${indent}</Path>` : `${open} />`;
}

function styleXaml(svg) {
  const names = new Set();
  const body = svg.tree.map((n) => partXaml(n, svg, ' '.repeat(28), names)).join('\n');
  return `    <Style x:Key="${styleKey(svg)}" TargetType="ContentControl">
        <Setter Property="Width" Value="${svg.size}" />
        <Setter Property="Height" Value="${svg.size}" />
        <Setter Property="IsTabStop" Value="False" />
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ContentControl">
                    <Viewbox Stretch="Uniform">
                        <Canvas Width="${svg.size}" Height="${svg.size}">
${body}
                        </Canvas>
                    </Viewbox>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>`;
}

// Every brush the theme dictionaries hold: the roles and surfaces, then the hyperlink brushes,
// each under its own Ab key and every WinUI key it stands for.
export function themeBrushes(tokens) {
  const links = hyperlinkTokens(tokens).flatMap((l) => [`Ab${l.name.charAt(0).toUpperCase()}${l.name.slice(1)}`, ...l.keys].map((xaml) => ({ ...l, xaml })));
  return [...roleTokens(tokens), ...surfaceTokens(tokens), ...links];
}

function typeStyle(t, tokens) {
  const setters = [
    ['FontSize', t.size],
    ['LineHeight', t.lineHeight],
    ['LineStackingStrategy', 'BlockLineHeight'],
    ...(t.semibold ? [['FontWeight', 'SemiBold']] : []),
    // Segoe UI Variable's Display optical size; Windows 10, which lacks it, falls back to Segoe UI.
    ...(t.display ? [['FontFamily', 'Segoe UI Variable Display, Segoe UI']] : []),
    ...(t.role === 'code' ? [['FontFamily', monoFamilies(tokens, 'xaml')]] : []),
    ['Typography.NumeralAlignment', 'Tabular'],
  ];
  return `    <Style x:Key="${t.xaml}" TargetType="TextBlock">
${setters.map(([p, v]) => `        <Setter Property="${p}" Value="${v}" />`).join('\n')}
    </Style>`;
}

export function designXaml(tokens, glyphs, icons) {
  const colours = themeBrushes(tokens);
  const theme = (key, pick) => `            <ResourceDictionary x:Key="${key}">
${colours.map((t) => `                <SolidColorBrush x:Key="${t.xaml}" Color="${pick(t)}" />`).join('\n')}
            </ResourceDictionary>`;
  const accent = accentShades(tokens);
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- ${xamlHeader('design/tokens.json, design/glyphs/*.svg and design/icons/*.svg')}

     Colour roles and surfaces (docs/design/ui.md §3) are brushes in every theme. A glyph or icon
     is a ContentControl style drawn in its Foreground:
       <ContentControl Style="{StaticResource AbGlyphNeeds}" Foreground="{ThemeResource AbNeeds}" />
     A glyph's knockout is the control's Background (the surface behind it); its moving part is
     the template part Spin or Orbit, turned by its RotateTransform. -->
<ResourceDictionary
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
    <ResourceDictionary.ThemeDictionaries>
${theme('Light', (t) => toXamlColor(t.light))}
${theme('Dark', (t) => toXamlColor(t.dark))}
${theme('HighContrast', (t) => `{ThemeResource ${SYSTEM_COLORS[t.hc].xaml}}`)}
    </ResourceDictionary.ThemeDictionaries>
${accent.length ? `
    <!-- WinUI's accent palette as Bridge (design/tokens.json color.accent): the controls that follow
         the system accent take it instead of the person's Windows accent. High contrast ignores it. -->
${accent.map((a) => `    <Color x:Key="${a.key}">${toXamlColor(a.value)}</Color>`).join('\n')}
` : ''}
    <!-- The monospace (docs/design/ui.md §4.1): the bundled font, then the fallback stack. -->
    <FontFamily x:Key="MonoFontFamily">${monoFamilies(tokens, 'xaml')}</FontFamily>
${radii(tokens).map((r) => `    <CornerRadius x:Key="${r.xaml}">${r.value}</CornerRadius>`).join('\n')}
${spaces(tokens).map((s) => `    <x:Double x:Key="${s.xaml}">${s.value}</x:Double>`).join('\n')}
${layoutSizes(tokens).map((s) => `    <x:Double x:Key="${s.xaml}">${s.value}</x:Double>`).join('\n')}

    <!-- The type ramp (docs/design/ui.md §4.3): tabular figures, no added tracking. -->
${typeRamp(tokens).map((t) => typeStyle(t, tokens)).join('\n')}

${[...glyphs, ...icons].map(styleXaml).join('\n')}
</ResourceDictionary>
`;
}

// The font files the app bundles, relative to its folder: what the XAML points at, and the OFL.
export function fontFiles(tokens) {
  const font = monoFont(tokens);
  return font ? [...font.faces.map((f) => `${font.appDir}/${f.file}.ttf`), `${font.appDir}/${font.license}`] : [];
}

export function designKeysCs(tokens, glyphs, icons) {
  const list = (xs) => xs.map((x) => `        "${x}",`).join('\n');
  return `// <auto-generated>
// ${xamlHeader('design/tokens.json, design/glyphs and design/icons').replace(/\n\s*/g, ' ')}
// </auto-generated>

namespace AgentBridge.App.Design;

// The keys DesignResources.xaml defines, for the self-test's check that each one resolves in
// every theme, and for code that looks a brush up by name.
static class DesignKeys
{
    public const string Source = "ms-appx:///Design/DesignResources.xaml";

    public static readonly string[] Brushes =
    [
${list(themeBrushes(tokens).map((t) => t.xaml))}
    ];

    // WinUI's accent palette, as Bridge: each key and its colour, #RRGGBB.
    public static readonly (string Key, string Color)[] AccentColors =
    [
${accentShades(tokens).map((a) => `        ("${a.key}", "${toXamlColor(a.value)}"),`).join('\n')}
    ];

    public static readonly string[] TypeStyles =
    [
${list(typeRamp(tokens).map((t) => t.xaml))}
    ];

    public static readonly string[] LayoutSizes =
    [
${list(layoutSizes(tokens).map((s) => s.xaml))}
    ];

    public static readonly string[] Glyphs =
    [
${list(glyphs.map(styleKey))}
    ];

    public static readonly string[] Icons =
    [
${list(icons.map(styleKey))}
    ];

    public const string MonoFontFamily = "MonoFontFamily";

    // The bundled monospace and its licence, as the app's folder holds them
    // (AgentBridge.App.csproj copies them from design/fonts).
    public static readonly string[] FontFiles =
    [
${list(fontFiles(tokens))}
    ];
}
`;
}

// The layout sizes for the app's platform-neutral view models (App.Core), which decide the
// panes by width and run on Linux CI too, where the XAML is not.
export function designLayoutCs(tokens) {
  return `// <auto-generated>
// ${xamlHeader('design/tokens.json').replace(/\n\s*/g, ' ')}
// </auto-generated>

namespace AgentBridge.App.Core;

// design/tokens.json layout (docs/design/ui.md §5.2, §7), in px.
public static class DesignLayout
{
${layoutSizes(tokens).map((s) => `    public const double ${s.cs} = ${s.value};`).join('\n')}
}
`;
}
